    // The light color mode with increased contrast.
    VisualSnapshot(id: "light-hc", mode: .lightHighContrast, locale: "en", rightToLeft: false, textSize: .default),
    // The dark color mode with increased contrast.
    VisualSnapshot(id: "dark-hc", mode: .darkHighContrast, locale: "en", rightToLeft: false, textSize: .default),
    // Arabic, right to left. What leads in English is on the right.
    VisualSnapshot(id: "rtl", mode: .light, locale: "ar", rightToLeft: true, textSize: .default),
